-- Additive local Phase 5 migration. Rendering and provider sync remain unconfigured.
begin;
create function marketing_private.video_timeline(v jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare x jsonb;k text;section text;ids text[]:='{}';dur numeric;len numeric;
begin
 if not coalesce(marketing_private.creative_keys(v,array['schema_version','width','height','duration','clips','audio','overlays','captions']),false) or v->'schema_version'<>'1' or not ((v->'width'='1080' and v->'height' in('1080','1350','1920')) or (v->'width'='1920' and v->'height'='1080')) or not marketing_private.creative_number(v->'duration',0.1,180) then return false;end if;
 dur:=(v->>'duration')::numeric;
 foreach section in array array['clips','audio','overlays','captions'] loop if jsonb_typeof(v->section)<>'array' then return false;end if;end loop;
 if jsonb_array_length(v->'clips')+jsonb_array_length(v->'audio')>100 or jsonb_array_length(v->'overlays')>100 or jsonb_array_length(v->'captions')>200 then return false;end if;
 foreach section in array array['clips','audio','overlays','captions'] loop
 for x in select * from jsonb_array_elements(v->section) loop
 if jsonb_typeof(x)<>'object' or exists(select 1 from jsonb_each(x) where value='null') then return false;end if;
 if not coalesce(marketing_private.creative_uuid(x->'id'),false) or lower(x->>'id')=any(ids) or jsonb_typeof(x->'locked') is distinct from 'boolean' or not marketing_private.creative_number(x->'start',0,dur) then return false;end if;ids:=array_append(ids,lower(x->>'id'));
 if section in('clips','audio') then
 if not marketing_private.creative_keys(x,array['id','source_id','track','start','in_point','out_point','volume','muted','fade_in','fade_out','fit','position_x','position_y','transition','transition_duration','locked']) or not coalesce(marketing_private.creative_uuid(x->'source_id'),false) or not marketing_private.creative_number(x->'track',0,4) or (x->>'track')::numeric<>trunc((x->>'track')::numeric) or jsonb_typeof(x->'muted') is distinct from 'boolean' or x->>'fit' not in('contain','cover') or x->>'transition' not in('cut','dissolve','slide') then return false;end if;
 foreach k in array array['in_point','out_point','fade_in','fade_out','volume','position_x','position_y','transition_duration'] loop if not marketing_private.creative_number(x->k,0,case when k in('volume','position_x','position_y','transition_duration') then 1 else 1800 end) then return false;end if;end loop;
 len:=(x->>'out_point')::numeric-(x->>'in_point')::numeric;
 if len<=0 or (x->>'start')::numeric+len>dur or (x->>'fade_in')::numeric+(x->>'fade_out')::numeric>len or (x->>'transition_duration')::numeric>len or (x->>'transition'='cut' and x->'transition_duration'<>'0') then return false;end if;
 else
 if not marketing_private.creative_number(x->'end',0,dur) or (x->>'end')::numeric<=(x->>'start')::numeric or jsonb_typeof(x->'text') is distinct from 'string' then return false;end if;
 if section='captions' then
 if not marketing_private.creative_keys(x,array['id','source_id','start','end','text','manually_verified','locked']) or not coalesce(marketing_private.creative_uuid(x->'source_id'),false) or jsonb_typeof(x->'manually_verified') is distinct from 'boolean' or not marketing_private.knowledge_text(x->>'text',1000,true) then return false;end if;
 else
 if not marketing_private.creative_keys(x,array['id','type','start','end','x','y','width','height','text','font_size','fill','opacity','animation','locked']) or x->>'type' not in('text','shape') or x->>'animation' not in('none','fade','slide','scale') or not marketing_private.knowledge_text(x->>'text',2000) or not marketing_private.creative_number(x->'font_size',12,240) or not marketing_private.creative_number(x->'opacity',0,1) or x->>'fill' !~ '^#[a-fA-F0-9]{6}$' then return false;end if;
 foreach k in array array['x','y','width','height'] loop if not marketing_private.creative_number(x->k,case when k in('width','height') then 1 else -12000 end,12000) then return false;end if;end loop;
 end if;end if;
 end loop;end loop;return true;
exception when others then return false;
end $$;
create table public.marketing_video_sources(
 id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),campaign_id uuid,title text not null check(marketing_private.knowledge_text(title,180,true)),kind text not null check(kind in('video','audio')),mime_type text not null,byte_size bigint not null check(byte_size>0),reported_sha256 text not null check(reported_sha256~'^[a-f0-9]{64}$'),duration numeric not null check(duration between 0.1 and 1800),width integer,height integer,storage_path text not null unique,status text not null default 'pending_upload' check(status in('pending_upload','ready')),provenance text not null check(marketing_private.knowledge_text(provenance,2000,true)),author text not null check(marketing_private.knowledge_text(author,200,true)),rights text not null default 'needs_review' check(rights in('needs_review','approved','internal_only','revoked')),allowed_channels text[] not null default '{}',valid_until timestamptz check(valid_until is null or isfinite(valid_until)),rights_reason text not null default '',creator_id uuid not null references public.profiles(id),reviewer_id uuid references public.profiles(id),version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(campaign_id,team_id) references public.marketing_campaigns(id,team_id),
 check((kind='video' and mime_type in('video/mp4','video/webm') and byte_size<=104857600 and width is not null and height is not null and width between 16 and 7680 and height between 16 and 7680 and width::bigint*height<=33000000) or (kind='audio' and mime_type in('audio/mpeg','audio/wav') and byte_size<=20971520 and width is null and height is null)));
create table public.marketing_video_projects(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),campaign_id uuid not null,content_id uuid not null references public.marketing_content_items(id),title text not null check(marketing_private.knowledge_text(title,180,true)),timeline jsonb not null check(marketing_private.video_timeline(timeline)),is_default boolean not null,parent_project_id uuid references public.marketing_video_projects(id),creator_id uuid not null references public.profiles(id),version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(campaign_id,team_id) references public.marketing_campaigns(id,team_id));
create unique index marketing_video_default on public.marketing_video_projects(content_id) where is_default;
create table public.marketing_video_versions(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),project_id uuid not null references public.marketing_video_projects(id),version integer not null,timeline jsonb not null,actor_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(project_id,version));
create table public.marketing_video_render_jobs(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),project_id uuid not null references public.marketing_video_projects(id),project_version integer not null,status text not null default 'not_configured' check(status in('not_configured','cancelled')),progress numeric check(progress is null),output_asset_id uuid check(output_asset_id is null),error text,creator_id uuid not null references public.profiles(id),version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.marketing_video_report_audit_logs(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),entity_id uuid not null,action text not null,actor_id uuid references public.profiles(id),snapshot jsonb not null,created_at timestamptz not null default now());
create function marketing_private.video_refs(v jsonb,team uuid,campaign uuid,preflight boolean default false) returns void language plpgsql set search_path='' as $$
declare section text;x jsonb;s public.marketing_video_sources;
begin
 if not marketing_private.video_timeline(v) then raise exception 'Invalid timeline' using errcode='22023';end if;
 perform 1 from public.marketing_video_sources where id in(select (e->>'source_id')::uuid from jsonb_array_elements((v->'clips')||(v->'audio')||(v->'captions')) e) order by id for share;
 foreach section in array array['clips','audio','captions'] loop for x in select * from jsonb_array_elements(v->section) loop
 select * into s from public.marketing_video_sources where id=(x->>'source_id')::uuid;
 if s.id is null or s.team_id<>team or (s.campaign_id is not null and s.campaign_id is distinct from campaign) or s.status<>'ready' then raise exception 'Source unavailable or wrong scope' using errcode='22023';end if;
 if (section='clips' and s.kind<>'video') or (section='audio' and s.kind<>'audio') or (section<>'captions' and (x->>'out_point')::numeric>s.duration) then raise exception 'Source kind or duration mismatch' using errcode='22023';end if;
 if section='captions' and not exists(select 1 from jsonb_array_elements((v->'clips')||(v->'audio')) c where c->>'source_id'=x->>'source_id' and (x->>'start')::numeric>=(c->>'start')::numeric and (x->>'end')::numeric<=(c->>'start')::numeric+(c->>'out_point')::numeric-(c->>'in_point')::numeric) then raise exception 'Caption must reference a covering source clip' using errcode='22023';end if;
 if preflight and (s.rights<>'approved' or not('facebook'=any(s.allowed_channels)) or (s.valid_until is not null and s.valid_until<=clock_timestamp()) or (section='captions' and x->'manually_verified'<>'true')) then raise exception 'Current Facebook rights and verified captions required' using errcode='22023';end if;
 end loop;end loop;
end $$;
create function marketing_private.video_command(p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare act text:=p_command->>'action';keys text[];k text;actor uuid:=auth.uid();team uuid;cv integer;newid uuid;result jsonb;tl jsonb;s public.marketing_video_sources;p public.marketing_video_projects;j public.marketing_video_render_jobs;i public.marketing_content_items;c public.marketing_campaigns;
begin
 if current_setting('role',true)<>'authenticated' then raise exception 'Authenticated session required' using errcode='42501';end if;
 keys:=case act when 'reserve_video_source' then array['action','team_id','campaign_id','title','kind','mime_type','byte_size','reported_sha256','duration','width','height','provenance','author'] when 'complete_video_source' then array['action','id','expected_version'] when 'review_video_source' then array['action','id','expected_version','rights','reason','allowed_channels','valid_until'] when 'create_video_project' then array['action','content_id','title','timeline'] when 'save_video_project' then array['action','id','expected_version','title','timeline'] when 'create_video_variant' then array['action','id','expected_version','title'] when 'restore_video_project' then array['action','id','expected_version','version_id'] when 'request_video_render' then array['action','id','expected_version'] when 'cancel_video_render' then array['action','id','expected_version','reason'] end;
 if keys is null or octet_length(p_command::text)>262144 or not coalesce(marketing_private.creative_keys(p_command,keys),false) then raise exception 'Invalid command fields' using errcode='22023';end if;
 foreach k in array keys loop
 if k in('id','content_id','team_id','campaign_id','version_id') and not(k='campaign_id' and p_command->k='null') and not coalesce(marketing_private.creative_uuid(p_command->k),false) then raise exception 'Invalid UUID' using errcode='22023';end if;
 if k in('expected_version','byte_size','width','height') and not(k in('width','height') and p_command->k='null') and (not marketing_private.creative_number(p_command->k,1,2147483647) or (p_command->>k)::numeric<>trunc((p_command->>k)::numeric)) then raise exception 'Invalid integer' using errcode='22023';end if;
 if k='duration' and not marketing_private.creative_number(p_command->k,0.1,1800) then raise exception 'Invalid duration' using errcode='22023';end if;
 if k in('title','provenance','author','reason','kind','mime_type','reported_sha256','rights') and (jsonb_typeof(p_command->k) is distinct from 'string' or not marketing_private.knowledge_text(p_command->>k,case k when 'title' then 180 when 'author' then 200 else 2000 end,true)) then raise exception 'Invalid text' using errcode='22023';end if;
 end loop;
 if act='reserve_video_source' then team:=(p_command->>'team_id')::uuid;
 elsif act in('complete_video_source','review_video_source') then select * into s from public.marketing_video_sources where id=(p_command->>'id')::uuid for update;team:=s.team_id;cv:=s.version;
 elsif act='cancel_video_render' then select * into j from public.marketing_video_render_jobs where id=(p_command->>'id')::uuid for update;team:=j.team_id;cv:=j.version;
 else
 if act='create_video_project' then select * into i from public.marketing_content_items where id=(p_command->>'content_id')::uuid;else select * into p from public.marketing_video_projects where id=(p_command->>'id')::uuid;select * into i from public.marketing_content_items where id=p.content_id;end if;
 select * into c from public.marketing_campaigns where id=i.campaign_id for update;select * into i from public.marketing_content_items where id=i.id for update;
 if p.id is not null then select * into p from public.marketing_video_projects where id=p.id for update;end if;team:=i.team_id;cv:=p.version;
 if i.id is null or c.status not in('draft','active') or i.publishing_status not in('draft','changes_requested') then raise exception 'Editable content and campaign required' using errcode='22023';end if;
 end if;
 if team is null then raise exception 'Entity unavailable' using errcode='42501';end if;
 perform marketing_private.publishing_actor(actor,team,act='review_video_source');
 if p_command ? 'expected_version' and cv is distinct from (p_command->>'expected_version')::integer then if not(act='complete_video_source' and s.status='ready' and s.version=2 and s.creator_id=actor and p_command->'expected_version'='1') then raise exception 'Version conflict' using errcode='40001';end if;end if;
 if act='reserve_video_source' then
 perform pg_advisory_xact_lock(hashtextextended('video-upload:'||actor,0));
 if (select count(*) from public.marketing_video_sources where creator_id=actor and status='pending_upload' and created_at>clock_timestamp()-interval '20 minutes')>=10 then raise exception 'Pending upload limit' using errcode='22023';end if;
 newid:=gen_random_uuid();insert into public.marketing_video_sources(id,team_id,campaign_id,title,kind,mime_type,byte_size,reported_sha256,duration,width,height,storage_path,provenance,author,creator_id) values(newid,team,(p_command->>'campaign_id')::uuid,p_command->>'title',p_command->>'kind',p_command->>'mime_type',(p_command->>'byte_size')::bigint,p_command->>'reported_sha256',(p_command->>'duration')::numeric,(p_command->>'width')::int,(p_command->>'height')::int,team||'/'||newid||'/original.'||case p_command->>'mime_type' when 'video/mp4' then 'mp4' when 'video/webm' then 'webm' when 'audio/mpeg' then 'mp3' when 'audio/wav' then 'wav' end,p_command->>'provenance',p_command->>'author',actor) returning * into s;result:=to_jsonb(s);
 elsif act='complete_video_source' then
 if s.creator_id<>actor then raise exception 'Reservation owner required' using errcode='42501';end if;
 if s.status='ready' then return to_jsonb(s);end if;
 if s.created_at<=clock_timestamp()-interval '20 minutes' or not exists(select 1 from storage.objects o where o.bucket_id='marketing-footage' and o.name=s.storage_path and o.metadata->>'mimetype'=s.mime_type and o.metadata->>'size'=s.byte_size::text) then raise exception 'Matching uploaded object metadata required' using errcode='22023';end if;
 update public.marketing_video_sources set status='ready',version=version+1,updated_at=clock_timestamp() where id=s.id returning * into s;result:=to_jsonb(s);
 elsif act='review_video_source' then
 if s.status<>'ready' or p_command->>'rights' not in('needs_review','approved','internal_only','revoked') or jsonb_typeof(p_command->'allowed_channels')<>'array' or exists(select 1 from jsonb_array_elements(p_command->'allowed_channels') x where jsonb_typeof(x)<>'string' or x#>>'{}' not in('facebook','internal')) or (select count(distinct x) from jsonb_array_elements(p_command->'allowed_channels') x)<>jsonb_array_length(p_command->'allowed_channels') or not marketing_private.creative_timestamp(p_command->'valid_until') then raise exception 'Invalid rights' using errcode='22023';end if;
 if p_command->>'rights'='approved' and (not(p_command->'allowed_channels' ? 'facebook') or (p_command->>'valid_until')::timestamptz<=clock_timestamp()) then raise exception 'Current Facebook rights required' using errcode='22023';end if;
 update public.marketing_video_sources set rights=p_command->>'rights',rights_reason=p_command->>'reason',allowed_channels=array(select jsonb_array_elements_text(p_command->'allowed_channels')),valid_until=(p_command->>'valid_until')::timestamptz,reviewer_id=actor,version=version+1,updated_at=clock_timestamp() where id=s.id returning * into s;result:=to_jsonb(s);
 elsif act='cancel_video_render' then
 if j.status<>'not_configured' then raise exception 'Job not cancellable' using errcode='22023';end if;
 update public.marketing_video_render_jobs set status='cancelled',error=p_command->>'reason',version=version+1,updated_at=clock_timestamp() where id=j.id returning * into j;result:=to_jsonb(j);
 elsif act='request_video_render' then
 perform marketing_private.video_refs(p.timeline,team,p.campaign_id,true);
 insert into public.marketing_video_render_jobs(team_id,project_id,project_version,error,creator_id) values(team,p.id,p.version,'Render worker is not configured. No media was produced.',actor) returning * into j;result:=to_jsonb(j);
 else
 if act='create_video_project' then select * into p from public.marketing_video_projects where content_id=i.id and is_default;if p.id is not null then return to_jsonb(p);end if;tl:=p_command->'timeline';
 elsif act='save_video_project' then tl:=p_command->'timeline';elsif act='create_video_variant' then tl:=p.timeline;
 else select timeline into tl from public.marketing_video_versions where id=(p_command->>'version_id')::uuid and project_id=p.id and team_id=team;if tl is null then raise exception 'Version unavailable' using errcode='42501';end if;end if;
 perform marketing_private.video_refs(tl,team,i.campaign_id);
 if act in('create_video_project','create_video_variant') then insert into public.marketing_video_projects(team_id,campaign_id,content_id,title,timeline,is_default,parent_project_id,creator_id) values(team,i.campaign_id,i.id,p_command->>'title',tl,act='create_video_project',case when act='create_video_variant' then p.id else null end,actor) returning * into p;
 else update public.marketing_video_projects set title=coalesce(p_command->>'title',title),timeline=tl,version=version+1,updated_at=clock_timestamp() where id=p.id returning * into p;end if;
 insert into public.marketing_video_versions(team_id,project_id,version,timeline,actor_id) values(team,p.id,p.version,p.timeline,actor);
 update public.marketing_content_items set version=version+1,updated_at=clock_timestamp() where id=i.id returning * into i;
 insert into public.marketing_revisions(team_id,campaign_id,entity_type,entity_id,version,action,actor_id,snapshot) values(team,i.campaign_id,'content',i.id,i.version,act,actor,to_jsonb(i)||jsonb_build_object('video_project',to_jsonb(p)));
 insert into public.marketing_audit_logs(team_id,entity_type,entity_id,version,action,actor_id,snapshot) values(team,'content',i.id,i.version,act,actor,to_jsonb(i));result:=to_jsonb(p);
 end if;
 insert into public.marketing_video_report_audit_logs(team_id,entity_id,action,actor_id,snapshot) values(team,(result->>'id')::uuid,act,actor,result);return result;
end $$;
create table public.marketing_organic_observations(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),connection_id uuid not null references public.marketing_connections(id),page_id text not null,post_id text not null,campaign_id uuid,content_line text not null check(content_line in('ColorMAP','Sharing','Meme','InsideME')),format text not null check(format in('text','image','carousel','video')),published_at timestamptz not null,"window" text not null check("window" in('24h','72h','7d')),eligibility text not null check(eligibility in('organic','paid','unknown')),reach bigint,views bigint,reactions bigint,comments bigint,shares bigint,clicks bigint,definitions jsonb not null,source_reference text not null,fetched_at timestamptz not null,created_at timestamptz not null default clock_timestamp(),foreign key(campaign_id,team_id) references public.marketing_campaigns(id,team_id));
alter table public.marketing_organic_observations add constraint marketing_observation_metrics check ((reach is null or reach between 0 and 9007199254740991) and (views is null or views between 0 and 9007199254740991) and (reactions is null or reactions between 0 and 9007199254740991) and (comments is null or comments between 0 and 9007199254740991) and (shares is null or shares between 0 and 9007199254740991) and (clicks is null or clicks between 0 and 9007199254740991)), add constraint marketing_observation_times check(isfinite(published_at) and isfinite(fetched_at) and fetched_at>=published_at);
create index marketing_organic_latest on public.marketing_organic_observations(connection_id,post_id,"window",fetched_at desc,created_at desc);
-- Installation boundary is private, persisted once and immutable; never infer older milestones.
create table marketing_private.report_tracking(singleton boolean primary key default true check(singleton),started_at timestamptz not null default clock_timestamp() check(isfinite(started_at)));
revoke all on marketing_private.report_tracking from public,anon,authenticated,service_role;
create table public.marketing_production_milestones(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),campaign_id uuid not null references public.marketing_campaigns(id),content_id uuid not null references public.marketing_content_items(id),kind text not null check(kind in('ready','review_started','reviewed')),occurred_at timestamptz not null default clock_timestamp(),due_at timestamptz,content_version integer not null,unique(content_id,kind));
create function marketing_private.video_milestone() returns trigger language plpgsql set search_path='' as $$ begin
 if new.production_status='ready' and (tg_op='INSERT' or old.production_status is distinct from new.production_status) then insert into public.marketing_production_milestones(team_id,campaign_id,content_id,kind,due_at,content_version) values(new.team_id,new.campaign_id,new.id,'ready',new.production_due_at,new.version) on conflict(content_id,kind) do nothing;end if;
 if new.publishing_status='in_review' and (tg_op='INSERT' or old.publishing_status is distinct from new.publishing_status) then insert into public.marketing_production_milestones(team_id,campaign_id,content_id,kind,due_at,content_version) values(new.team_id,new.campaign_id,new.id,'review_started',new.review_due_at,new.version) on conflict(content_id,kind) do nothing;end if;
 if new.publishing_status in('approved','changes_requested') and tg_op='UPDATE' and old.publishing_status='in_review' then insert into public.marketing_production_milestones(team_id,campaign_id,content_id,kind,due_at,content_version) values(new.team_id,new.campaign_id,new.id,'reviewed',new.review_due_at,new.version) on conflict(content_id,kind) do nothing;end if;return new;end $$;
create trigger marketing_production_milestone after insert or update on public.marketing_content_items for each row execute function marketing_private.video_milestone();
-- Record cutover after acquiring the trigger DDL lock in this transaction.
insert into marketing_private.report_tracking default values;
create table public.marketing_reports(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),campaign_id uuid,kind text not null check(kind in('weekly','monthly')),title text not null check(marketing_private.knowledge_text(title,180,true)),period_start date not null,period_end date not null,metrics jsonb not null,narrative text not null default '' check(marketing_private.knowledge_text(narrative,12000)),metrics_hash text not null,creator_id uuid not null references public.profiles(id),version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(campaign_id,team_id) references public.marketing_campaigns(id,team_id));
create table public.marketing_report_versions(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),report_id uuid not null references public.marketing_reports(id),version integer not null,snapshot jsonb not null,actor_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(report_id,version));
create table public.marketing_report_share_approvals(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),report_id uuid not null references public.marketing_reports(id),report_version integer not null,metrics_hash text not null,narrative_hash text not null,approver_id uuid not null references public.profiles(id),reason text not null,created_at timestamptz not null default now(),unique(report_id,report_version));
create table public.marketing_insights(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.marketing_teams(id),campaign_id uuid,report_id uuid not null references public.marketing_reports(id),kind text not null,title text not null,recommendation text not null,evidence jsonb not null,status text not null default 'proposed' check(status in('proposed','accepted','rejected','in_progress','completed')),reason text not null default '',actor_id uuid references public.profiles(id),version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(campaign_id,team_id) references public.marketing_campaigns(id,team_id));
create function marketing_private.report_ingest_command(p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare keys text[]:=array['team_id','connection_id','page_id','post_id','campaign_id','content_line','format','published_at','window','eligibility','reach','views','reactions','comments','shares','clicks','definitions','source_reference','fetched_at'];k text;c public.marketing_connections;o public.marketing_organic_observations;
begin
 if current_setting('role',true)<>'service_role' then raise exception 'Service gateway required' using errcode='42501';end if;
 if octet_length(p_command::text)>262144 or not coalesce(marketing_private.creative_keys(p_command,keys),false) then raise exception 'Invalid observation fields' using errcode='22023';end if;
 foreach k in array array['team_id','connection_id','campaign_id'] loop if not(k='campaign_id' and p_command->k='null') and not coalesce(marketing_private.creative_uuid(p_command->k),false) then raise exception 'Invalid identity' using errcode='22023';end if;end loop;
 foreach k in array array['reach','views','reactions','comments','shares','clicks'] loop if p_command->k<>'null' and (not marketing_private.creative_number(p_command->k,0,9007199254740991) or (p_command->>k)::numeric<>trunc((p_command->>k)::numeric)) then raise exception 'Metrics must be nullable safe nonnegative integers' using errcode='22023';end if;end loop;
 foreach k in array array['published_at','fetched_at'] loop if p_command->k='null' or not marketing_private.creative_timestamp(p_command->k) then raise exception 'Invalid timestamp' using errcode='22023';end if;end loop;
 foreach k in array array['page_id','post_id','source_reference'] loop if jsonb_typeof(p_command->k)<>'string' or not marketing_private.knowledge_text(p_command->>k,500,true) then raise exception 'Provenance required' using errcode='22023';end if;end loop;
 if not coalesce(marketing_private.creative_keys(p_command->'definitions',array['reach','views','reactions','comments','shares','clicks']),false) then raise exception 'Exact metric definitions required' using errcode='22023';end if;
 foreach k in array array['reach','views','reactions','comments','shares','clicks'] loop if jsonb_typeof(p_command->'definitions'->k)<>'string' or not marketing_private.knowledge_text(p_command->'definitions'->>k,500,true) then raise exception 'Invalid definition' using errcode='22023';end if;end loop;
 select * into c from public.marketing_connections where id=(p_command->>'connection_id')::uuid for share;
 if c.id is null or c.team_id<>(p_command->>'team_id')::uuid or c.page_id<>p_command->>'page_id' or c.status<>'connected' or c.verified_at is null or c.capabilities->'organic_metrics' is distinct from 'true' or (c.expires_at is not null and c.expires_at<=clock_timestamp()) then raise exception 'Verified owned Page organic capability required' using errcode='42501';end if;
 if (p_command->>'fetched_at')::timestamptz>clock_timestamp() or (p_command->>'published_at')::timestamptz>(p_command->>'fetched_at')::timestamptz or (p_command->>'fetched_at')::timestamptz<(p_command->>'published_at')::timestamptz+(case p_command->>'window' when '24h' then interval '24 hours' when '72h' then interval '72 hours' when '7d' then interval '7 days' end) then raise exception 'Observation window is incomplete' using errcode='22023';end if;
 insert into public.marketing_organic_observations(team_id,connection_id,page_id,post_id,campaign_id,content_line,format,published_at,"window",eligibility,reach,views,reactions,comments,shares,clicks,definitions,source_reference,fetched_at) values(c.team_id,c.id,c.page_id,p_command->>'post_id',(p_command->>'campaign_id')::uuid,p_command->>'content_line',p_command->>'format',(p_command->>'published_at')::timestamptz,p_command->>'window',p_command->>'eligibility',(p_command->>'reach')::bigint,(p_command->>'views')::bigint,(p_command->>'reactions')::bigint,(p_command->>'comments')::bigint,(p_command->>'shares')::bigint,(p_command->>'clicks')::bigint,p_command->'definitions',p_command->>'source_reference',(p_command->>'fetched_at')::timestamptz) returning * into o;
 insert into public.marketing_video_report_audit_logs(team_id,entity_id,action,snapshot) values(o.team_id,o.id,'ingest_organic',to_jsonb(o));return to_jsonb(o);
end $$;
create function marketing_private.report_metrics(team uuid,campaign uuid,ds date,de date) returns jsonb language plpgsql set search_path='' as $$
declare ts timestamptz:=ds::timestamp at time zone 'Asia/Ho_Chi_Minh';te timestamptz:=(de+1)::timestamp at time zone 'Asia/Ho_Chi_Minh';at_time timestamptz:=clock_timestamp();production jsonb;organic jsonb;warnings jsonb:='[]';total bigint;eligible bigint;metric text;val numeric;num numeric;den numeric;defs jsonb;refs jsonb;observations jsonb;manifest jsonb;tracking_started timestamptz;
begin
 select started_at into strict tracking_started from marketing_private.report_tracking where singleton;
 select jsonb_build_object('planned',count(*),'ready',count(*) filter(where production_status='ready')) into production from public.marketing_content_items where team_id=team and (campaign is null or campaign_id=campaign) and created_at>=ts and created_at<te and created_at<=at_time;
 select production||jsonb_build_object('reviewed',case when ts>=tracking_started and ts<=at_time then count(*) filter(where kind='reviewed') else null end,'on_time',case when count(*) filter(where kind='ready' and due_at is not null)>0 then count(*) filter(where kind='ready' and due_at is not null and occurred_at<=due_at) else null end,'on_time_denominator',count(*) filter(where kind='ready' and due_at is not null)) into production from public.marketing_production_milestones where team_id=team and (campaign is null or campaign_id=campaign) and occurred_at>=ts and occurred_at<te and occurred_at<=at_time;
 select production||jsonb_build_object('review_hours',avg(extract(epoch from (done.occurred_at-started.occurred_at))/3600),'review_sample_size',count(*)) into production from public.marketing_production_milestones done join public.marketing_production_milestones started on started.content_id=done.content_id and started.kind='review_started' where done.kind='reviewed' and done.team_id=team and (campaign is null or done.campaign_id=campaign) and done.occurred_at>=ts and done.occurred_at<te and done.occurred_at<=at_time and done.occurred_at>=started.occurred_at;
 select production||jsonb_build_object('published',count(distinct content_id)) into production from public.marketing_publishing_jobs where team_id=team and (campaign is null or campaign_id=campaign) and status='published' and remote_id is not null and receipt is not null and updated_at>=ts and updated_at<te and updated_at<=at_time;
 -- Latest observation wins before period/campaign filtering: corrected classification cannot revive an older sample.
 select coalesce(jsonb_agg(to_jsonb(q)),'[]') into observations from (select distinct on(connection_id,post_id,"window") * from public.marketing_organic_observations where team_id=team and "window"='7d' and fetched_at<=at_time and created_at<=at_time order by connection_id,post_id,"window",fetched_at desc,created_at desc,id desc) q where q.published_at>=ts and q.published_at<te and (campaign is null or q.campaign_id=campaign);
 select count(*),count(*) filter(where x->>'eligibility'='organic'),jsonb_build_object('eligible_posts',count(*) filter(where x->>'eligibility'='organic'),'excluded_paid',count(*) filter(where x->>'eligibility'='paid'),'unknown_posts',count(*) filter(where x->>'eligibility'='unknown')) into total,eligible,organic from jsonb_array_elements(observations) x;
 -- A mixed definition is not a comparable sample; never silently sum it.
 foreach metric in array array['reach','views','reactions','comments','shares','clicks'] loop
 select case when count(*)>0 and count(*)=count(nullif(x->>metric,'')) and count(distinct x->'definitions'->>metric)=1 and sum((x->>metric)::numeric)<=9007199254740991 then sum((x->>metric)::numeric) else null end into val from jsonb_array_elements(observations) x where x->>'eligibility'='organic';
 organic:=organic||jsonb_build_object(metric,val);
 end loop;
 num:=(organic->>'reactions')::numeric+(organic->>'comments')::numeric+(organic->>'shares')::numeric;den:=(organic->>'reach')::numeric;
 if num>9007199254740991 then num:=null;end if;
 select coalesce(jsonb_agg(distinct x->>'source_reference'),'[]') into refs from jsonb_array_elements(observations)x where x->>'eligibility'='organic';
 select coalesce(jsonb_agg(jsonb_build_object('id',x->'id','connection_id',x->'connection_id','page_id',x->'page_id','post_id',x->'post_id','window',x->'window','eligibility',x->'eligibility','source_reference',x->'source_reference','fetched_at',x->'fetched_at','definitions',x->'definitions') order by x->>'connection_id',x->>'post_id',x->>'id'),'[]') into manifest from jsonb_array_elements(observations)x;
 defs:=jsonb_build_object('reach','people; sum of complete comparable 7d organic post reach, not unique across posts','views','views; complete comparable 7d organic sample','reactions','reactions; complete comparable 7d organic sample','comments','comments; complete comparable 7d organic sample','shares','shares; complete comparable 7d organic sample','clicks','clicks; complete comparable 7d organic sample','engagement_rate','percent; (reactions + comments + shares) / reach * 100; same complete eligible sample','window','7d; latest fetched observation per connection and post');
 organic:=organic||jsonb_build_object('numerator',num,'denominator',den,'engagement_rate',case when num is not null and den>0 then num/den*100 else null end,'definitions',defs,'references',refs,'observations',manifest);
 if eligible=0 then warnings:=warnings||'"No eligible 7d organic observations; missing metrics are null."'::jsonb;elsif exists(select 1 from jsonb_each(organic) where key in('reach','views','reactions','comments','shares','clicks') and value='null') then warnings:=warnings||'"Organic metrics have incomplete or incompatible definition coverage."'::jsonb;end if;
 if (organic->>'unknown_posts')::bigint>0 then warnings:=warnings||'"Unknown paid eligibility excluded."'::jsonb;end if;
 if ts<tracking_started then warnings:=warnings||'"Report period begins before reliable milestone tracking; historical review count is unavailable, and on-time/review-duration values cover observed samples only."'::jsonb;end if;
 if ts>at_time then warnings:=warnings||'"Report period has not started; review count is unavailable."'::jsonb;elsif te>at_time then warnings:=warnings||'"Report period is ongoing; observed counts cover only data available as of the snapshot time."'::jsonb;end if;
 return jsonb_build_object('as_of',at_time,'period_start',ds,'period_end',de,'production',production,'organic',organic,'coverage',jsonb_build_object('production_tracking_started_at',tracking_started,'production','Created-period planned/ready; first milestone-period on-time/review; verified published job updates. Asia/Ho_Chi_Minh.','organic',case when eligible=0 then 'unavailable' when exists(select 1 from jsonb_each(organic) where key in('reach','views','reactions','comments','shares','clicks') and value='null') then 'partial' else 'complete_observed_sample' end,'warnings',warnings));
end $$;
create function marketing_private.report_command(p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare act text:=p_command->>'action';keys text[];k text;team uuid;actor uuid:=auth.uid();r public.marketing_reports;ins public.marketing_insights;approval public.marketing_report_share_approvals;result jsonb;m jsonb;ds date;de date;evidence jsonb;
begin
 if current_setting('role',true)<>'authenticated' then raise exception 'Authenticated session required' using errcode='42501';end if;
 keys:=case act when 'build_report' then array['action','team_id','campaign_id','kind','title','period_start','period_end'] when 'edit_report' then array['action','id','expected_version','title','narrative'] when 'approve_report_share' then array['action','id','expected_version','reason','confirmed'] when 'feedback_insight' then array['action','id','expected_version','status','reason'] end;
 if keys is null or octet_length(p_command::text)>262144 or not coalesce(marketing_private.creative_keys(p_command,keys),false) then raise exception 'Invalid report command fields' using errcode='22023';end if;
 foreach k in array keys loop
 if k in('id','team_id','campaign_id') and not(k='campaign_id' and p_command->k='null') and not coalesce(marketing_private.creative_uuid(p_command->k),false) then raise exception 'Invalid UUID' using errcode='22023';end if;
 if k='expected_version' and (not marketing_private.creative_number(p_command->k,1,2147483647) or (p_command->>k)::numeric<>trunc((p_command->>k)::numeric)) then raise exception 'Invalid version' using errcode='22023';end if;
 if k in('title','narrative','reason') and (jsonb_typeof(p_command->k)<>'string' or not marketing_private.knowledge_text(p_command->>k,case k when 'title' then 180 when 'narrative' then 12000 else 2000 end,k<>'narrative')) then raise exception 'Invalid text' using errcode='22023';end if;end loop;
 if act='build_report' then team:=(p_command->>'team_id')::uuid;
 elsif act='feedback_insight' then select * into ins from public.marketing_insights where id=(p_command->>'id')::uuid for update;team:=ins.team_id;if ins.version is distinct from (p_command->>'expected_version')::int then raise exception 'Version conflict' using errcode='40001';end if;
 else select * into r from public.marketing_reports where id=(p_command->>'id')::uuid for update;team:=r.team_id;if r.version is distinct from (p_command->>'expected_version')::int then raise exception 'Version conflict' using errcode='40001';end if;end if;
 if team is null then raise exception 'Entity unavailable' using errcode='42501';end if;perform marketing_private.publishing_actor(actor,team,act='approve_report_share');
 if act='build_report' then
 foreach k in array array['period_start','period_end'] loop if jsonb_typeof(p_command->k)<>'string' or p_command->>k !~ '^[1-9][0-9]{3}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid period' using errcode='22023';end if;end loop;
 ds:=(p_command->>'period_start')::date;de:=(p_command->>'period_end')::date;
 if p_command->>'kind' not in('weekly','monthly') or (p_command->>'kind'='weekly' and de<>ds+6) or (p_command->>'kind'='monthly' and (extract(day from ds)<>1 or de<>(ds+interval '1 month'-interval '1 day')::date)) then raise exception 'Exact weekly or monthly period required' using errcode='22023';end if;
 m:=marketing_private.report_metrics(team,(p_command->>'campaign_id')::uuid,ds,de);
 insert into public.marketing_reports(team_id,campaign_id,kind,title,period_start,period_end,metrics,metrics_hash,creator_id) values(team,(p_command->>'campaign_id')::uuid,p_command->>'kind',p_command->>'title',ds,de,m,encode(sha256(convert_to(m::text,'UTF8')),'hex'),actor) returning * into r;
 select jsonb_build_object('content_ids',coalesce(jsonb_agg(id order by id),'[]'),'count',count(*),'as_of',m->'as_of') into evidence from public.marketing_content_items where team_id=team and (r.campaign_id is null or campaign_id=r.campaign_id) and created_at>=ds::timestamp at time zone 'Asia/Ho_Chi_Minh' and created_at<(de+1)::timestamp at time zone 'Asia/Ho_Chi_Minh' and production_status<>'ready' and created_at<=(m->>'as_of')::timestamptz;
 if (evidence->>'count')::int>0 then insert into public.marketing_insights(team_id,campaign_id,report_id,kind,title,recommendation,evidence) values(team,r.campaign_id,r.id,'production_gap','Planned content is not ready','Review the listed content and decide whether follow-up is needed. No changes are applied automatically.',evidence);end if;
 result:=to_jsonb(r);
 elsif act='edit_report' then update public.marketing_reports set title=p_command->>'title',narrative=p_command->>'narrative',version=version+1,updated_at=clock_timestamp() where id=r.id returning * into r;result:=to_jsonb(r);
 elsif act='approve_report_share' then
 if p_command->'confirmed' is distinct from 'true' then raise exception 'Explicit exact version confirmation required' using errcode='22023';end if;
 insert into public.marketing_report_share_approvals(team_id,report_id,report_version,metrics_hash,narrative_hash,approver_id,reason) values(team,r.id,r.version,r.metrics_hash,encode(sha256(convert_to(r.narrative,'UTF8')),'hex'),actor,p_command->>'reason') on conflict(report_id,report_version) do nothing;
 select * into approval from public.marketing_report_share_approvals where report_id=r.id and report_version=r.version;result:=to_jsonb(approval);
 else
 if p_command->>'status' not in('proposed','accepted','rejected','in_progress','completed') then raise exception 'Invalid feedback status' using errcode='22023';end if;
 update public.marketing_insights set status=p_command->>'status',reason=p_command->>'reason',actor_id=actor,version=version+1,updated_at=clock_timestamp() where id=ins.id returning * into ins;result:=to_jsonb(ins);
 end if;
 if act in('build_report','edit_report') then insert into public.marketing_report_versions(team_id,report_id,version,snapshot,actor_id) values(team,r.id,r.version,to_jsonb(r),actor);end if;
 insert into public.marketing_video_report_audit_logs(team_id,entity_id,action,actor_id,snapshot) values(team,(result->>'id')::uuid,act,actor,result);return result;
end $$;
create function marketing_private.video_report_guard() returns trigger language plpgsql set search_path='' as $$
declare mutable text[];
begin
 mutable:=case tg_table_name when 'marketing_video_sources' then array['status','rights','allowed_channels','valid_until','rights_reason','reviewer_id','version','updated_at'] when 'marketing_video_projects' then array['title','timeline','version','updated_at'] when 'marketing_video_render_jobs' then array['status','error','version','updated_at'] when 'marketing_reports' then array['title','narrative','version','updated_at'] when 'marketing_insights' then array['status','reason','actor_id','version','updated_at'] end;
 if tg_op='DELETE' or mutable is null then raise exception 'Immutable history' using errcode='42501';end if;
 if (to_jsonb(new)-mutable) is distinct from (to_jsonb(old)-mutable) then raise exception 'Immutable identity or snapshot' using errcode='42501';end if;return new;
end $$;
create trigger report_tracking_immutable before update or delete on marketing_private.report_tracking for each row execute function marketing_private.video_report_guard();
do $$ declare t text;begin foreach t in array array['marketing_video_sources','marketing_video_projects','marketing_video_versions','marketing_video_render_jobs','marketing_video_report_audit_logs','marketing_organic_observations','marketing_production_milestones','marketing_reports','marketing_report_versions','marketing_report_share_approvals','marketing_insights'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('grant select on public.%I to authenticated',t);execute format('create policy phase5_select on public.%I for select to authenticated using(marketing_private.can_read(team_id))',t);execute format('create trigger phase5_guard before update or delete on public.%I for each row execute function marketing_private.video_report_guard()',t);
 end loop;end $$;
create function marketing_private.video_storage(path text,upload boolean,meta jsonb default null) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.marketing_video_sources s where s.storage_path=path and marketing_private.can_read(s.team_id) and
 case when upload then s.creator_id=auth.uid() and s.status='pending_upload' and s.created_at>clock_timestamp()-interval '20 minutes' and exists(select 1 from public.user_roles where user_id=auth.uid() and role in('Admin','PR Leader','PR Representative')) and (s.kind<>'audio' or s.byte_size<=20971520) and jsonb_typeof(meta)='object' and meta->>'mimetype'=s.mime_type and meta->>'size'=s.byte_size::text
 else s.status='ready' and s.rights<>'revoked' and (s.valid_until is null or s.valid_until>clock_timestamp()) end)
$$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('marketing-footage','marketing-footage',false,104857600,array['video/mp4','video/webm','audio/mpeg','audio/wav']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy marketing_footage_insert on storage.objects for insert to authenticated with check(bucket_id='marketing-footage' and marketing_private.video_storage(name,true,metadata));
create policy marketing_footage_select on storage.objects for select to authenticated using(bucket_id='marketing-footage' and marketing_private.video_storage(name,false));
create policy marketing_footage_insert_scope on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'marketing-footage' or marketing_private.video_storage(name,true,metadata));
create policy marketing_footage_read_scope on storage.objects as restrictive for select to authenticated using(bucket_id<>'marketing-footage' or marketing_private.video_storage(name,false));
create policy marketing_footage_no_update on storage.objects as restrictive for update to authenticated using(bucket_id<>'marketing-footage') with check(bucket_id<>'marketing-footage');
create policy marketing_footage_no_delete on storage.objects as restrictive for delete to authenticated using(bucket_id<>'marketing-footage');
-- Defense in depth against unrelated permissive object policies: originals cannot be replaced.
create function marketing_private.video_storage_guard() returns trigger language plpgsql set search_path='' as $$ begin
 if (old.bucket_id='marketing-footage' or (tg_op='UPDATE' and new.bucket_id='marketing-footage')) and current_setting('role',true)='authenticated' then raise exception 'Immutable source object' using errcode='42501';end if;return case when tg_op='DELETE' then old else new end;
end $$;
create trigger marketing_footage_immutable before update or delete on storage.objects for each row execute function marketing_private.video_storage_guard();
-- WIP timelines do not block existing caption/image review. Phase 4 has no video publication mode.
create function public.marketing_video_command(p_command jsonb) returns jsonb language sql security invoker set search_path='' as $$ select marketing_private.video_command(p_command) $$;
create function public.marketing_report_command(p_command jsonb) returns jsonb language sql security invoker set search_path='' as $$ select marketing_private.report_command(p_command) $$;
create function public.marketing_report_ingest_command(p_command jsonb) returns jsonb language sql security invoker set search_path='' as $$ select marketing_private.report_ingest_command(p_command) $$;
revoke all on function public.marketing_video_command(jsonb),public.marketing_report_command(jsonb),public.marketing_report_ingest_command(jsonb) from public,anon,authenticated,service_role;
do $$ declare f record;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='marketing_private' and (p.proname like 'video_%' or p.proname like 'report_%') loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.sig);end loop;end $$;
grant execute on function public.marketing_video_command(jsonb),public.marketing_report_command(jsonb),marketing_private.video_command(jsonb),marketing_private.report_command(jsonb),marketing_private.video_storage(text,boolean,jsonb) to authenticated;
grant execute on function public.marketing_report_ingest_command(jsonb),marketing_private.report_ingest_command(jsonb) to service_role;
commit;
